CREATE TYPE public.app_role AS ENUM ('security_analyst','security_supervisor','organization_verification_officer','organization_administrator','public_visitor');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, preferences jsonb NOT NULL DEFAULT '{}');
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK (id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles_read ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_security_access() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role IN ('security_analyst','security_supervisor')); $$;
REVOKE ALL ON FUNCTION public.has_security_access() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_security_access() TO authenticated,service_role;
CREATE FUNCTION public.create_staff_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name) VALUES (NEW.id,left(coalesce(NEW.raw_user_meta_data->>'display_name',''),120)); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'public_visitor'); RETURN NEW; END $$;
CREATE TRIGGER create_staff_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_staff_profile();
CREATE TABLE public.security_templates (id text PRIMARY KEY, payload jsonb NOT NULL);
GRANT SELECT ON public.security_templates TO authenticated; GRANT ALL ON public.security_templates TO service_role;
ALTER TABLE public.security_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY security_template_read ON public.security_templates FOR SELECT TO authenticated USING (public.has_security_access());
CREATE TABLE public.security_workspaces (user_id uuid PRIMARY KEY, payload jsonb NOT NULL, revision integer NOT NULL DEFAULT 0);
GRANT SELECT,INSERT,UPDATE ON public.security_workspaces TO authenticated; GRANT ALL ON public.security_workspaces TO service_role;
ALTER TABLE public.security_workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY security_workspace_read ON public.security_workspaces FOR SELECT TO authenticated USING (public.has_security_access() AND user_id=auth.uid());
CREATE POLICY security_workspace_insert ON public.security_workspaces FOR INSERT TO authenticated WITH CHECK (public.has_security_access() AND user_id=auth.uid());
CREATE POLICY security_workspace_update ON public.security_workspaces FOR UPDATE TO authenticated USING (public.has_security_access() AND user_id=auth.uid()) WITH CHECK (public.has_security_access() AND user_id=auth.uid());
CREATE TABLE public.security_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient uuid, input jsonb NOT NULL, received_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.security_reports TO authenticated; GRANT ALL ON public.security_reports TO service_role;
ALTER TABLE public.security_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY security_report_read ON public.security_reports FOR SELECT TO authenticated USING (public.has_security_access() AND (recipient IS NULL OR recipient=auth.uid()));
CREATE POLICY security_report_delete ON public.security_reports FOR DELETE TO authenticated USING (public.has_security_access() AND (recipient IS NULL OR recipient=auth.uid()));
CREATE FUNCTION public.flagged_message_values(candidate_values text[], workspace_user uuid DEFAULT NULL) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH source AS (SELECT coalesce((SELECT payload FROM public.security_workspaces WHERE user_id=workspace_user),(SELECT payload FROM public.security_templates WHERE id='original')) AS payload), indicators AS (SELECT i->>'value' AS value FROM source, jsonb_array_elements(payload->'alerts') a, jsonb_array_elements(a->'indicators') i WHERE a->>'status' IN ('escalated','confirmed')) SELECT coalesce(array_agg(DISTINCT c),'{}'::text[]) FROM unnest(candidate_values) c WHERE EXISTS (SELECT 1 FROM indicators WHERE lower(regexp_replace(regexp_replace(regexp_replace(value,'^https?://','','i'),'^www\.','','i'),'[/\s]+$','','g'))=lower(regexp_replace(regexp_replace(regexp_replace(c,'^https?://','','i'),'^www\.','','i'),'[/\s]+$','','g')));
$$;
REVOKE ALL ON FUNCTION public.flagged_message_values(text[],uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.flagged_message_values(text[],uuid) TO anon,authenticated,service_role;
CREATE FUNCTION public.submit_security_report(report_input jsonb, workspace_user uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF length(report_input::text)>20000 OR coalesce(length(report_input->>'sender'),0)>500 OR report_input->>'channel' NOT IN ('email','sms','phone','website','social','other') THEN RAISE EXCEPTION 'Invalid report'; END IF; INSERT INTO public.security_reports(recipient,input) VALUES(workspace_user,report_input); END $$;
REVOKE ALL ON FUNCTION public.submit_security_report(jsonb,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_security_report(jsonb,uuid) TO anon,authenticated,service_role;